import{_ as c,C as h,o as s,c as u,a9 as r,b as o,w as t,a as n,E as a,a8 as d}from"./chunks/framework.BOiBTRPC.js";const k=JSON.parse('{"title":"Data Platform Design Case Studies","description":"ByteByteGo-style end-to-end data platform designs — lakehouse for 50 teams, a real-time feature platform, a global metrics layer, a GDPR-grade PII platform, a legacy-to-cloud migration, a consistent-hashing distributed cache tier, and a metrics/monitoring pipeline — each with layered diagrams, capacity math, decision logs, and failure modes.","frontmatter":{"title":"Data Platform Design Case Studies","description":"ByteByteGo-style end-to-end data platform designs — lakehouse for 50 teams, a real-time feature platform, a global metrics layer, a GDPR-grade PII platform, a legacy-to-cloud migration, a consistent-hashing distributed cache tier, and a metrics/monitoring pipeline — each with layered diagrams, capacity math, decision logs, and failure modes."},"headers":[],"relativePath":"system-design/platform-designs.md","filePath":"system-design/platform-designs.md"}'),g={name:"system-design/platform-designs.md"};function m(p,e,f,b,y,v){const i=h("Mermaid"),l=h("QuizCard");return s(),u("div",null,[e[10]||(e[10]=r('<h1 id="data-platform-design-case-studies" tabindex="-1">Data Platform Design Case Studies <a class="header-anchor" href="#data-platform-design-case-studies" aria-label="Permalink to &quot;Data Platform Design Case Studies&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — &quot;Design the data platform&quot; is the senior/staff interview prompt that separates people who have built one from people who have only used one. These five case studies practice the full arc — requirements, layered architecture, capacity math, decision log, failure modes, and what breaks at 10x — on the designs you will actually be asked for.</p></blockquote><p>Each case follows the same skeleton — the same skeleton a strong interview answer follows:</p><ol><li><strong>Requirements</strong> — functional plus non-functional, with the numbers that drive the design.</li><li><strong>Architecture</strong> — layered diagram, numbered data flow.</li><li><strong>Capacity estimate</strong> — five lines of arithmetic, narrating which number drives the design.</li><li><strong>Decision log</strong> — the trade-offs you chose and why, not the tools you chose.</li><li><strong>Failure modes</strong> — what breaks and the mitigation pattern.</li><li><strong>At 10x</strong> — which assumption dies first.</li></ol><p>The pattern vocabulary underneath every case lives in <a href="/Data-Knowledge/system-design/pipeline-design.html">Designing Reliable Pipelines</a> — idempotency, DLQs, contracts, SLOs. Storage and format choices are covered in <a href="/Data-Knowledge/cloud/lakehouse-platforms.html">Lakehouse Platforms</a>. This chapter applies them, it does not reteach them.</p><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>In a platform-design interview, the deliverable is not a diagram — it is the <em>decision log</em>. Interviewers probe &quot;why not the alternative?&quot; five times more often than &quot;what does this box do?&quot; Sketch fast, argue trade-offs slowly.</p></div><h2 id="case-1-—-greenfield-lakehouse-for-a-50-team-org" tabindex="-1">Case 1 — Greenfield lakehouse for a 50-team org <a class="header-anchor" href="#case-1-—-greenfield-lakehouse-for-a-50-team-org" aria-label="Permalink to &quot;Case 1 — Greenfield lakehouse for a 50-team org&quot;">​</a></h2><p><strong>The ask.</strong> A company with ~50 product teams, five legacy data silos, and no shared platform wants a lakehouse: batch + stream ingestion, governed data products, self-service analytics, and ML feature reuse — without creating a 40-person central bottleneck.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Design implication</th></tr></thead><tbody><tr><td>50 teams onboard in 12 months</td><td>Self-service is the product — templates, paved paths, guardrails over gates</td></tr><tr><td>Batch + stream sources</td><td>One ingestion framework with two runtimes, not two stacks</td></tr><tr><td>Regulated + unregulated data coexist</td><td>Governance and classification in the platform, not per team</td></tr><tr><td>BI and ML consumers</td><td>Two serving surfaces: governed marts for BI, feature tables for ML</td></tr><tr><td>Central team of ~8</td><td>Platform team owns primitives; product teams own data products — data mesh-lite</td></tr></tbody></table>',9)),(s(),o(d,null,{default:t(()=>[a(i,{id:"mermaid-111",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Ingest%5B%22Ingestion%20layer%22%5D%0A%20%20%20%20%20%20%20%20I1%5B%22Managed%20connectors%20%E2%80%94%20batch%2C%20CDC%2C%20files%22%5D%0A%20%20%20%20%20%20%20%20I2%5B%22Event%20bus%20%E2%80%94%20Kafka%20with%20schema%20registry%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Lake%5B%22Lakehouse%20%E2%80%94%20medallion%22%5D%0A%20%20%20%20%20%20%20%20B%5B%22Bronze%20%E2%80%94%20raw%2C%20immutable%2C%20replayable%22%5D%0A%20%20%20%20%20%20%20%20S%5B%22Silver%20%E2%80%94%20conformed%2C%20deduped%2C%20contracts%20enforced%22%5D%0A%20%20%20%20%20%20%20%20G%5B%22Gold%20%E2%80%94%20domain-owned%20data%20products%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Gov%5B%22Governance%20plane%22%5D%0A%20%20%20%20%20%20%20%20C1%5B%22Catalog%20%E2%80%94%20discovery%2C%20lineage%2C%20ownership%22%5D%0A%20%20%20%20%20%20%20%20C2%5B%22Access%20control%20%E2%80%94%20tag-based%20policies%22%5D%0A%20%20%20%20%20%20%20%20C3%5B%22Quality%20%E2%80%94%20contract%20checks%2C%20SLO%20monitors%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Serve%5B%22Serving%20layer%22%5D%0A%20%20%20%20%20%20%20%20W%5B%22Warehouse%20endpoints%20%E2%80%94%20BI%20marts%22%5D%0A%20%20%20%20%20%20%20%20F%5B%22Feature%20tables%20%E2%80%94%20ML%22%5D%0A%20%20%20%20%20%20%20%20Q%5B%22Query%20federation%20%E2%80%94%20ad%20hoc%22%5D%0A%20%20%20%20end%0A%20%20%20%20I1%20--%3E%7C%221%20land%22%7C%20B%0A%20%20%20%20I2%20--%3E%7C%222%20land%22%7C%20B%0A%20%20%20%20B%20--%3E%7C%223%20conform%22%7C%20S%0A%20%20%20%20S%20--%3E%7C%224%20publish%22%7C%20G%0A%20%20%20%20G%20--%3E%7C%225a%20serve%22%7C%20W%0A%20%20%20%20G%20--%3E%7C%225b%20serve%22%7C%20F%0A%20%20%20%20B%20-.-%3E%20C1%0A%20%20%20%20S%20-.-%3E%20C1%0A%20%20%20%20G%20-.-%3E%20C1%0A%20%20%20%20S%20-.-%3E%20C3%0A%20%20%20%20G%20-.-%3E%20C3%0A%20%20%20%20W%20-.-%3E%20C2%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[11]||(e[11]=r('<ol><li>Connectors and producers land data into <strong>bronze</strong> — immutable, partitioned by arrival, replayable.</li><li>Stream events route through the bus with registry-enforced schemas; bad events DLQ at the boundary.</li><li>Bronze→silver conformance runs as platform-templated jobs: dedupe, contract validation, PII tagging.</li><li>Silver→gold is <strong>domain-owned</strong>: each product team publishes gold tables with an owner, SLO, and catalog entry — the mesh-lite contract.</li><li>Serving splits: BI hits governed marts via warehouse endpoints; ML reads feature tables; ad hoc goes through federation with scan quotas.</li></ol><h3 id="capacity-estimate" tabindex="-1">Capacity estimate <a class="header-anchor" href="#capacity-estimate" aria-label="Permalink to &quot;Capacity estimate&quot;">​</a></h3><ul><li><strong>Ingestion</strong>: 200 sources × ~5 GB/day avg ≈ <strong>1 TB/day landed</strong>; streams add ~2k events/s sustained — trivial for a 6-12 partition bus.</li><li><strong>Storage</strong>: 1 TB/day × 365 × ~2.5x replication-and-layer overhead ≈ <strong>~1 PB/year</strong> across medallion layers; Parquet compression cuts raw landing ~4x.</li><li><strong>Compute driver</strong>: not ingest — it is <em>concurrency</em>. 50 teams × ad hoc analysts is where warehouse costs spike; quotas and autosuspend matter more than cluster size.</li><li><strong>Team math</strong>: 8 platform engineers can support ~50 teams only if onboarding is self-service; at &gt;10 tickets/team for onboarding, the platform team becomes the bottleneck — measure onboarding lead time as the platform SLO.</li></ul><h3 id="decision-log" tabindex="-1">Decision log <a class="header-anchor" href="#decision-log" aria-label="Permalink to &quot;Decision log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Options</th><th>Call</th><th>Why</th></tr></thead><tbody><tr><td>Ownership model</td><td>Central DE team vs full mesh vs mesh-lite</td><td><strong>Mesh-lite</strong> — central primitives, domain-owned gold</td><td>Full mesh needs platform maturity the org lacks; pure central does not scale past ~15 teams</td></tr><tr><td>Table format</td><td>Delta vs Iceberg vs Hudi</td><td><strong>Iceberg</strong></td><td>Multi-engine support, no vendor lock on the catalog</td></tr><tr><td>Catalog</td><td>Open-source vs cloud-native</td><td>Cloud-native with open API</td><td>8-person team should not run a metastore</td></tr><tr><td>Compute</td><td>Spark everywhere vs SQL-first warehouse</td><td>SQL-first, Spark for heavy transforms</td><td>Analysts outnumber engineers 10:1</td></tr></tbody></table><h3 id="failure-modes" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Mitigation</th></tr></thead><tbody><tr><td>Team publishes gold with no owner or SLO</td><td>Catalog enforces registration on publish; unregistered tables get read-only then archived</td></tr><tr><td>A team&#39;s silver job corrupts shared bronze</td><td>Bronze is append-only and platform-owned — domain jobs are read-only on bronze</td></tr><tr><td>Self-service sprawl — 500 tables nobody owns</td><td>Ownership TTL: tables without an active owner emit warnings, then get de-listed</td></tr><tr><td>One team&#39;s runaway query starves the warehouse</td><td>Workload isolation + per-team scan quotas</td></tr></tbody></table><h3 id="what-changes-at-10x" tabindex="-1">What changes at 10x <a class="header-anchor" href="#what-changes-at-10x" aria-label="Permalink to &quot;What changes at 10x&quot;">​</a></h3><ul><li><strong>500 teams</strong>: the catalog becomes the bottleneck — discovery, lineage depth, and policy evaluation. You need domain-level namespaces and delegated stewardship, not a flat catalog.</li><li><strong>10 TB/day</strong>: bronze-to-silver conformance cost dominates; move to incremental/micro-batch reads and drop full-scan jobs.</li><li><strong>Governance</strong>: manual stewardship review dies at ~100 products; automate classification and policy-as-code.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>The most common failure of this design is organizational, not technical: the platform team keeps owning gold &quot;temporarily&quot; because domains are not ready. Six months later the central team owns 200 pipelines and the mesh never happens. Set the ownership-transfer deadline in the platform charter, not per team.</p></div><h2 id="case-2-—-real-time-personalization-and-feature-platform" tabindex="-1">Case 2 — Real-time personalization and feature platform <a class="header-anchor" href="#case-2-—-real-time-personalization-and-feature-platform" aria-label="Permalink to &quot;Case 2 — Real-time personalization and feature platform&quot;">​</a></h2><p><strong>The ask.</strong> Events from web + mobile feed a personalization model that must serve features in single-digit milliseconds, while the <em>same</em> features train the model offline — without training-serving skew.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Design implication</th></tr></thead><tbody><tr><td>p99 feature fetch under 10 ms</td><td>Online store must be a KV lookup, not a query</td></tr><tr><td>Same feature logic for train and serve</td><td>One feature definition compiled to both paths</td></tr><tr><td>Features must be point-in-time correct</td><td>Training set built via point-in-time joins, not &quot;latest values&quot;</td></tr><tr><td>100k feature fetches/s peak</td><td>Online store sized for reads, not writes</td></tr><tr><td>New features weekly</td><td>Feature registry as code with CI validation</td></tr></tbody></table>',13)),(s(),o(d,null,{default:t(()=>[a(i,{id:"mermaid-377",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Stream%5B%22Streaming%20path%22%5D%0A%20%20%20%20%20%20%20%20E%5B%22Clickstream%20events%22%5D%20--%3E%20K%5B%22Kafka%20topics%22%5D%0A%20%20%20%20%20%20%20%20K%20--%3E%20FL%5B%22Flink%20feature%20jobs%20%E2%80%94%20windowed%20aggregates%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Batch%5B%22Batch%20path%22%5D%0A%20%20%20%20%20%20%20%20L%5B%22Lakehouse%20tables%22%5D%20--%3E%20BJ%5B%22Spark%20feature%20jobs%20%E2%80%94%20same%20definitions%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Registry%5B%22Feature%20registry%22%5D%0A%20%20%20%20%20%20%20%20R%5B%22Feature%20definitions%20as%20code%20%E2%80%94%20source%20of%20truth%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Online%5B%22Online%20serving%22%5D%0A%20%20%20%20%20%20%20%20OS%5B%22Online%20store%20%E2%80%94%20Redis%20or%20DynamoDB%22%5D%0A%20%20%20%20%20%20%20%20FS%5B%22Feature%20service%20%E2%80%94%20gRPC%2C%20single-digit%20ms%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Offline%5B%22Offline%20store%22%5D%0A%20%20%20%20%20%20%20%20OFF%5B%22Point-in-time%20feature%20tables%20%E2%80%94%20lakehouse%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Consumers%5B%22Consumers%22%5D%0A%20%20%20%20%20%20%20%20M%5B%22Model%20serving%20%E2%80%94%20inference%22%5D%0A%20%20%20%20%20%20%20%20T%5B%22Training%20pipelines%22%5D%0A%20%20%20%20end%0A%20%20%20%20R%20-.-%3E%7C%22compiles%20to%22%7C%20FL%0A%20%20%20%20R%20-.-%3E%7C%22compiles%20to%22%7C%20BJ%0A%20%20%20%20FL%20--%3E%7C%221%20write%20latest%22%7C%20OS%0A%20%20%20%20FL%20--%3E%7C%222%20write%20history%22%7C%20OFF%0A%20%20%20%20BJ%20--%3E%7C%223%20backfill%20history%22%7C%20OFF%0A%20%20%20%20OS%20--%3E%7C%224%20fetch%22%7C%20FS%0A%20%20%20%20FS%20--%3E%7C%225%20serve%22%7C%20M%0A%20%20%20%20OFF%20--%3E%7C%226%20point-in-time%20join%22%7C%20T%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=r('<ol><li>Flink consumes events and maintains windowed feature state.</li><li>Latest feature values write to the online store keyed by entity; full history lands in the offline store.</li><li>Batch jobs compute the <em>same</em> feature definitions over lakehouse history — the registry generates both jobs from one definition.</li><li>At inference, the feature service does one KV lookup per entity — no computation in the hot path.</li><li>Training pulls features via <strong>point-in-time joins</strong>: for each labeled event, the feature value <em>as of</em> that event time — never the latest value.</li></ol><h3 id="capacity-estimate-1" tabindex="-1">Capacity estimate <a class="header-anchor" href="#capacity-estimate-1" aria-label="Permalink to &quot;Capacity estimate&quot;">​</a></h3><ul><li><strong>Event rate</strong>: 50k events/s peak → ~3-5 Flink tasks per feature group with checkpointed state; state size driven by window × cardinality, not rate.</li><li><strong>Online store</strong>: 10M entities × ~2 KB feature vector ≈ <strong>20 GB</strong> — fits in a modest Redis cluster; 100k reads/s × small values is comfortably within DynamoDB on-demand or a 3-shard Redis.</li><li><strong>Latency budget</strong>: p99 = network 1-2 ms + KV lookup 1-3 ms + serialization ~1 ms → headroom inside 10 ms only if <em>nothing computes</em> on read. Any per-request aggregation blows the budget.</li><li><strong>Offline</strong>: point-in-time joins over 90 days of features is the expensive operation — a 1M-label training set joining 50 features scans terabytes; partition pruning by label-date is mandatory.</li></ul><h3 id="decision-log-1" tabindex="-1">Decision log <a class="header-anchor" href="#decision-log-1" aria-label="Permalink to &quot;Decision log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Options</th><th>Call</th><th>Why</th></tr></thead><tbody><tr><td>Online store</td><td>Redis vs DynamoDB vs purpose-built KV</td><td>Redis if sub-5ms p99 required, DynamoDB if ops simplicity wins</td><td>Redis wins latency, loses on managed ops — pick per p99 target</td></tr><tr><td>Feature parity</td><td>Dual implementations vs one definition, two compilers</td><td><strong>One definition, two engines</strong></td><td>Dual implementations <em>will</em> drift; the registry is the whole point</td></tr><tr><td>Point-in-time correctness</td><td>As-of join at training time vs snapshot tables</td><td>As-of joins on event-time partitioned features</td><td>Snapshots explode storage; event-time partitions make as-of joins cheap</td></tr><tr><td>Freshness</td><td>Full streaming vs hybrid</td><td><strong>Hybrid</strong> — stream for recency features, batch for lifetime aggregates</td><td>Streaming everything is 5-10x cost for features that do not need it</td></tr></tbody></table><h3 id="failure-modes-1" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes-1" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Mitigation</th></tr></thead><tbody><tr><td>Training-serving skew — different logic in the two paths</td><td>Single registry definition; CI check compares online vs offline values on a sampled entity set</td></tr><tr><td>Feature service returns stale or missing features</td><td>TTL per feature + null-default contract; monitor serving-vs-offline freshness drift</td></tr><tr><td>Late events corrupt a windowed feature</td><td>Event-time semantics + allowed-lateness watermark; corrections write a new version, never mutate served values silently</td></tr><tr><td>Online store hot-keyed by celebrity entities</td><td>Key-level load shedding; cache hot entities at the feature-service layer</td></tr></tbody></table><h3 id="what-changes-at-10x-1" tabindex="-1">What changes at 10x <a class="header-anchor" href="#what-changes-at-10x-1" aria-label="Permalink to &quot;What changes at 10x&quot;">​</a></h3><ul><li><strong>1M fetches/s</strong>: the feature service tier — not the store — becomes the bottleneck; add entity-level caching and connection pooling before scaling the KV.</li><li><strong>1000s of features</strong>: registry CI and parity sampling become the slow path; you need feature lineage to prune unused definitions.</li><li><strong>Cross-region</strong>: online store replication lag causes regional skew — decide per feature whether regional consistency or global freshness wins.</li></ul><details class="details custom-block"><summary>Point-in-time correctness — the detail interviews probe</summary><p>If your training set uses &quot;current&quot; feature values, you train on the answer — leakage. A model trained on post-event features looks great offline and fails in production. The fix is always the same: features stored with event-time validity, training sets materialized with as-of joins keyed on label timestamp. This is the single most-tested concept in feature-platform design — name it before being asked.</p></details><h2 id="case-3-—-global-metrics-and-semantic-layer" tabindex="-1">Case 3 — Global metrics and semantic layer <a class="header-anchor" href="#case-3-—-global-metrics-and-semantic-layer" aria-label="Permalink to &quot;Case 3 — Global metrics and semantic layer&quot;">​</a></h2><p><strong>The ask.</strong> Fifty dashboards disagree on &quot;revenue.&quot; Build one metrics platform: definitions-as-code, one computation path for dashboards and APIs, fast enough for interactive BI.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Design implication</th></tr></thead><tbody><tr><td>One definition per metric, org-wide</td><td>Metrics-as-code in a repo, code-reviewed like application code</td></tr><tr><td>Dashboards, APIs, embedded analytics</td><td>Metrics served through one query layer, not per-tool logic</td></tr><tr><td>Interactive latency under 2 s</td><td>Pre-aggregation and caching tiers, not raw scans</td></tr><tr><td>Stream + batch sources</td><td>Unified pipeline — no lambda architecture maintaining two logic paths</td></tr><tr><td>Self-serve new metrics</td><td>Declarative metric definitions with guardrails, not free SQL</td></tr></tbody></table>',13)),(s(),o(d,null,{default:t(()=>[a(i,{id:"mermaid-643",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Sources%5B%22Sources%22%5D%0A%20%20%20%20%20%20%20%20EV%5B%22Event%20streams%22%5D%0A%20%20%20%20%20%20%20%20WH%5B%22Batch%20tables%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Unified%5B%22Unified%20computation%22%5D%0A%20%20%20%20%20%20%20%20U%5B%22Stream-batch%20unified%20jobs%20%E2%80%94%20event-time%20aggregates%22%5D%0A%20%20%20%20%20%20%20%20AGG%5B%22Pre-aggregated%20metric%20tables%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Semantic%5B%22Semantic%20layer%22%5D%0A%20%20%20%20%20%20%20%20MD%5B%22Metric%20definitions%20as%20code%20%E2%80%94%20reviewed%2C%20versioned%22%5D%0A%20%20%20%20%20%20%20%20QL%5B%22Query%20layer%20%E2%80%94%20compiles%20metric%20requests%20to%20SQL%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Cache%5B%22Caching%20tiers%22%5D%0A%20%20%20%20%20%20%20%20CH1%5B%22Result%20cache%20%E2%80%94%20dashboard%20queries%22%5D%0A%20%20%20%20%20%20%20%20CH2%5B%22Aggregate%20cache%20%E2%80%94%20common%20dimension%20slices%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Apps%5B%22Consumers%22%5D%0A%20%20%20%20%20%20%20%20DB%5B%22Dashboards%22%5D%0A%20%20%20%20%20%20%20%20API%5B%22Metrics%20API%22%5D%0A%20%20%20%20%20%20%20%20NB%5B%22Notebook%20access%22%5D%0A%20%20%20%20end%0A%20%20%20%20EV%20--%3E%7C%221%22%7C%20U%0A%20%20%20%20WH%20--%3E%7C%222%22%7C%20U%0A%20%20%20%20U%20--%3E%7C%223%20materialize%22%7C%20AGG%0A%20%20%20%20MD%20--%3E%7C%224%20compile%22%7C%20QL%0A%20%20%20%20AGG%20--%3E%20QL%0A%20%20%20%20QL%20--%3E%7C%225%20check%20cache%22%7C%20CH1%0A%20%20%20%20QL%20--%3E%7C%226%22%7C%20CH2%0A%20%20%20%20CH1%20--%3E%20DB%0A%20%20%20%20QL%20--%3E%20DB%0A%20%20%20%20QL%20--%3E%20API%0A%20%20%20%20QL%20--%3E%20NB%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[n(" Loading... ",-1)])]),_:1})),e[13]||(e[13]=r('<ol><li>Events and batch sources feed <strong>one</strong> computation layer — event-time aggregates that work identically on stream and historical data.</li><li>Metric definitions live as code: <code>metric: weekly_active_users, agg: count_distinct, entity: user_id, window: 7d</code> — reviewed, versioned, compiled.</li><li>The query layer resolves a metric + dimensions + filters into optimized SQL against pre-aggregated tables.</li><li>Two cache tiers: raw result cache for repeat dashboard queries, and a shared aggregate cache for common dimension slices.</li><li>Every consumer — BI, API, notebooks — resolves through the same layer, so &quot;revenue&quot; cannot diverge by tool.</li></ol><h3 id="capacity-estimate-2" tabindex="-1">Capacity estimate <a class="header-anchor" href="#capacity-estimate-2" aria-label="Permalink to &quot;Capacity estimate&quot;">​</a></h3><ul><li><strong>Traffic</strong>: 5k daily dashboard users × 20 queries ≈ 100k metric queries/day — small. The driver is <strong>unique query shapes</strong>: 50 metrics × 20 dimensions × time grains ≈ combinatorial materialization space.</li><li><strong>Pre-aggregation</strong>: a fact table at 1 TB/day rolls up to ~10-50 GB/day at the common grain — a 20-100x scan reduction; materialization cost amortizes after ~5-10 reads per aggregate.</li><li><strong>Cache hit rate</strong>: dashboards refresh identically — 80-90% result-cache hit rate is normal; the remaining 10-20% of unique shapes are where the platform spends money.</li><li><strong>Freshness cost curve</strong>: 15-minute freshness ≈ 1.5-2x the cost of hourly; sub-minute ≈ 5-10x. Price it, then negotiate.</li></ul><h3 id="decision-log-2" tabindex="-1">Decision log <a class="header-anchor" href="#decision-log-2" aria-label="Permalink to &quot;Decision log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Options</th><th>Call</th><th>Why</th></tr></thead><tbody><tr><td>Where metrics live</td><td>In BI tool vs dbt models vs dedicated semantic layer</td><td><strong>Dedicated layer</strong> — BI tools come and go</td><td>Metric logic in Looker/dbt is trapped logic; the layer outlives the tool</td></tr><tr><td>Lambda vs unified</td><td>Separate stream and batch pipelines vs one event-time framework</td><td><strong>Unified</strong></td><td>Two code paths always produce two answers; the whole problem is one answer</td></tr><tr><td>Pre-aggregation</td><td>Always-on vs on-demand materialization</td><td>On-demand with a promotion rule</td><td>Materializing every combination is waste; promote aggregates after N reads</td></tr><tr><td>Metric change rollout</td><td>Immediate vs versioned</td><td><strong>Versioned with a canary window</strong></td><td>A metric redefinition silently changes every dashboard — roll it out like a deploy</td></tr></tbody></table><h3 id="failure-modes-2" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes-2" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Mitigation</th></tr></thead><tbody><tr><td>Two tools compute &quot;revenue&quot; differently</td><td>Force all reads through the query layer; block direct fact-table access for served metrics</td></tr><tr><td>Pre-aggregate drift from source</td><td>Reconciliation job: nightly full-scan comparison vs aggregates, alert on divergence</td></tr><tr><td>Metric definition change silently alters dashboards</td><td>Definitions are versioned; changes emit a diff report and require consumer ack for breaking changes</td></tr><tr><td>Cache serves stale results past freshness SLO</td><td>Cache TTL tied to data freshness watermark, not a fixed clock TTL</td></tr></tbody></table><h3 id="what-changes-at-10x-2" tabindex="-1">What changes at 10x <a class="header-anchor" href="#what-changes-at-10x-2" aria-label="Permalink to &quot;What changes at 10x&quot;">​</a></h3><ul><li><strong>10k+ metrics</strong>: discovery and deduplication become the problem — the platform needs metric lineage and &quot;does this already exist?&quot; search, or teams re-declare the same metric five ways.</li><li><strong>1M queries/day</strong>: the query layer itself needs horizontal scaling and per-consumer quotas.</li><li><strong>Sub-minute freshness demands</strong>: the unified layer&#39;s micro-batch cadence becomes cost-dominant; tier freshness per metric — the CEO dashboard and a debug metric should not share a freshness class.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>The semantic layer&#39;s hardest problem is not SQL generation — it is <em>organizational adoption</em>. If teams can still query the raw fact table, they will. The platform wins when the governed path is also the <em>easiest</em> path — that is a product decision, not an architecture one.</p></div><h2 id="case-4-—-compliance-grade-pii-platform" tabindex="-1">Case 4 — Compliance-grade PII platform <a class="header-anchor" href="#case-4-—-compliance-grade-pii-platform" aria-label="Permalink to &quot;Case 4 — Compliance-grade PII platform&quot;">​</a></h2><p><strong>The ask.</strong> GDPR/CCPA apply. Design ingestion where PII is tokenized at the boundary, access is purpose-scoped, and a deletion request provably removes a user from lake, warehouse, and caches.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Design implication</th></tr></thead><tbody><tr><td>PII never raw in the lake</td><td>Tokenize at ingest — raw PII lives only in a vault</td></tr><tr><td>Purpose-based access</td><td>Access decisions on &quot;why,&quot; not just &quot;who&quot; — policy per dataset-purpose pair</td></tr><tr><td>Right to erasure across all systems</td><td>Tombstone propagation with a verifiable delete manifest</td></tr><tr><td>Audit everything</td><td>Immutable lineage and access log, itself queryable</td></tr><tr><td>Analytics still works on tokenized data</td><td>Deterministic tokens preserve joinability without revealing identity</td></tr></tbody></table>',13)),(s(),o(d,null,{default:t(()=>[a(i,{id:"mermaid-909",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Boundary%5B%22Ingestion%20boundary%22%5D%0A%20%20%20%20%20%20%20%20SRC%5B%22Sources%22%5D%20--%3E%20TOK%5B%22Tokenizer%20%E2%80%94%20vault-backed%2C%20deterministic%22%5D%0A%20%20%20%20%20%20%20%20TOK%20--%3E%7C%221%20tokenized%20records%22%7C%20LK%5B%22Lake%20%E2%80%94%20tokenized%20zone%22%5D%0A%20%20%20%20%20%20%20%20TOK%20--%3E%7C%222%20raw%20PII%20to%20vault%20only%22%7C%20VAULT%5B%22PII%20vault%20%E2%80%94%20isolated%2C%20encrypted%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Zones%5B%22Storage%20zones%22%5D%0A%20%20%20%20%20%20%20%20LK%20--%3E%7C%223%20curated%22%7C%20CUR%5B%22Curated%20zone%20%E2%80%94%20tokenized%20joins%22%5D%0A%20%20%20%20%20%20%20%20CUR%20--%3E%7C%224%20serve%22%7C%20WH%5B%22Warehouse%20%2B%20caches%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Access%5B%22Access%20control%22%5D%0A%20%20%20%20%20%20%20%20ABAC%5B%22Purpose-based%20policies%20%E2%80%94%20dataset%20plus%20declared%20purpose%22%5D%0A%20%20%20%20%20%20%20%20AUDIT%5B%22Audit%20log%20%E2%80%94%20every%20access%20and%20every%20policy%20decision%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Deletion%5B%22Deletion%20propagation%22%5D%0A%20%20%20%20%20%20%20%20REQ%5B%22Erasure%20request%22%5D%20--%3E%20MAN%5B%22Delete%20manifest%20%E2%80%94%20user%20key%22%5D%0A%20%20%20%20%20%20%20%20MAN%20--%3E%7C%225a%20tombstone%20in%20lake%22%7C%20LK%0A%20%20%20%20%20%20%20%20MAN%20--%3E%7C%225b%20delete%20rows%22%7C%20CUR%0A%20%20%20%20%20%20%20%20MAN%20--%3E%7C%225c%20purge%22%7C%20WH%0A%20%20%20%20%20%20%20%20MAN%20--%3E%7C%225d%20invalidate%22%7C%20VAULT%0A%20%20%20%20%20%20%20%20MAN%20--%3E%7C%226%20verify%22%7C%20VER%5B%22Verification%20job%20%E2%80%94%20scans%20each%20system%22%5D%0A%20%20%20%20end%0A%20%20%20%20WH%20-.-%3E%20ABAC%0A%20%20%20%20CUR%20-.-%3E%20ABAC%0A%20%20%20%20ABAC%20-.-%3E%20AUDIT%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[n(" Loading... ",-1)])]),_:1})),e[14]||(e[14]=r('<ol><li>All records pass through the tokenizer; raw PII fields are replaced with deterministic tokens — the same person always gets the same token, so joins still work.</li><li>Raw PII exists only in an isolated vault with its own access path and its own, stricter, audit trail. 3-4. All downstream systems — curated lake, warehouse, caches — contain only tokenized data; a breach of the analytics zone is not a PII breach.</li><li>Erasure: a delete manifest drives tombstones in the lake, row deletes in curated zones, cache invalidation, and vault invalidation of the token→PII mapping.</li><li>A verification job scans each system and attests completion — &quot;we believe we deleted&quot; is not compliance.</li></ol><h3 id="capacity-estimate-3" tabindex="-1">Capacity estimate <a class="header-anchor" href="#capacity-estimate-3" aria-label="Permalink to &quot;Capacity estimate&quot;">​</a></h3><ul><li><strong>Tokenizer throughput</strong>: 50k records/s × ~200 μs/lookup = trivially within a small autoscaled service; the vault write is the latency driver — batch PII writes, stream tokens.</li><li><strong>Deletion volume</strong>: assume ~0.1% of a 50M-user base per month ≈ 50k erasures/month — a per-user-row scan over petabytes is infeasible; you need <strong>partition pruning by user cohort</strong> or a maintained key→partition index.</li><li><strong>Storage overhead</strong>: token adds ~16-32 B/row — negligible. The real cost is the <em>second</em> copy of every PII join path: vault + tokenized.</li><li><strong>Audit log</strong>: every query + policy decision logged → ~10-100M rows/day; this log is itself a data platform with retention and query needs.</li></ul><h3 id="decision-log-3" tabindex="-1">Decision log <a class="header-anchor" href="#decision-log-3" aria-label="Permalink to &quot;Decision log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Options</th><th>Call</th><th>Why</th></tr></thead><tbody><tr><td>Tokenization vs encryption at rest</td><td>Tokenize at boundary vs encrypt columns</td><td><strong>Tokenize</strong></td><td>Encryption still leaves PII readable wherever it is decrypted; tokens make the analytics zone PII-free by construction</td></tr><tr><td>Delete strategy</td><td>In-place deletes vs tombstone + rewrite</td><td><strong>Tombstone manifest + scheduled partition rewrite</strong></td><td>In-place deletes on a lake are partial and unverifiable; tombstones are replayable and auditable</td></tr><tr><td>Vault access</td><td>Detokenization service vs direct vault queries</td><td>Detokenization service with purpose check</td><td>Every identity resolution is a policy decision — centralize it or lose it</td></tr><tr><td>Access model</td><td>RBAC vs purpose-based ABAC</td><td><strong>Purpose-based</strong></td><td>GDPR is about purpose, not roles; &quot;analyst&quot; is not a purpose</td></tr></tbody></table><h3 id="failure-modes-3" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes-3" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Mitigation</th></tr></thead><tbody><tr><td>A pipeline lands raw PII by bypassing the tokenizer</td><td>Boundary is enforced at the connector layer — no write path exists that skips tokenization; scanners audit the lake for PII patterns anyway</td></tr><tr><td>Delete manifest misses a system</td><td>The manifest is generated from <em>lineage</em> — systems not in lineage cannot hold the user&#39;s data in the first place</td></tr><tr><td>Cache retains a deleted user past SLA</td><td>Deletion includes explicit cache invalidation keys; verification job re-checks caches at T+SLA</td></tr><tr><td>Token collision or re-identification via join</td><td>Tokens are vaulted and rotating per purpose; cross-purpose joining requires the detokenization service — which logs it</td></tr><tr><td>Vault itself is breached</td><td>Vault is isolated, minimal-retention, and access is purpose-gated with human review for bulk detokenization</td></tr></tbody></table><h3 id="what-changes-at-10x-3" tabindex="-1">What changes at 10x <a class="header-anchor" href="#what-changes-at-10x-3" aria-label="Permalink to &quot;What changes at 10x&quot;">​</a></h3><ul><li><strong>10x erasure volume</strong>: per-request scanning dies — you need a precomputed key→location index so deletion is a lookup, not a scan.</li><li><strong>Multi-region</strong>: data residency adds a placement dimension — &quot;delete EU user&quot; must know which regions legally held the data; lineage gains a region tag.</li><li><strong>More regulations</strong>: retention rules diverge per jurisdiction — the manifest becomes a per-purpose, per-region policy evaluation, not one delete list.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>The silent failure of this design is <em>shadow copies</em>: exports, notebook checkpoints, local parquet files, model training snapshots. They bypass every control above. Compliance platforms fail audits on data that left the platform, not data inside it. The mitigation is export governance — approved extract paths only — which is the least technical and most ignored part of the design.</p></div><h2 id="case-5-—-legacy-on-prem-etl-to-cloud-lakehouse-migration" tabindex="-1">Case 5 — Legacy on-prem ETL to cloud lakehouse migration <a class="header-anchor" href="#case-5-—-legacy-on-prem-etl-to-cloud-lakehouse-migration" aria-label="Permalink to &quot;Case 5 — Legacy on-prem ETL to cloud lakehouse migration&quot;">​</a></h2><p><strong>The ask.</strong> A 10-year-old Informatica/on-prem stack with 3,000 jobs migrates to a cloud lakehouse. Zero downtime, provable parity, and a rollback story — the strangler-fig pattern.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Design implication</th></tr></thead><tbody><tr><td>Zero business disruption</td><td>Run old and new in parallel; cut over per pipeline, not big bang</td></tr><tr><td>3,000 legacy jobs</td><td>Migration is a <em>program</em> — inventory, prioritize, automate</td></tr><tr><td>Numbers must match</td><td>Dual-run parity framework with per-table gates</td></tr><tr><td>Some pipelines can&#39;t move</td><td>Hybrid coexistence is a long phase, not an edge case</td></tr><tr><td>Rollback must be real</td><td>Old stack stays warm until a pipeline proves itself in prod</td></tr></tbody></table>',13)),(s(),o(d,null,{default:t(()=>[a(i,{id:"mermaid-1178",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Legacy%5B%22Legacy%20stack%20%E2%80%94%20stays%20warm%22%5D%0A%20%20%20%20%20%20%20%20LS%5B%22On-prem%20sources%22%5D%20--%3E%20LE%5B%22Legacy%20ETL%20engine%22%5D%0A%20%20%20%20%20%20%20%20LE%20--%3E%20LDW%5B%22Legacy%20warehouse%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20New%5B%22New%20lakehouse%22%5D%0A%20%20%20%20%20%20%20%20NS%5B%22Same%20sources%22%5D%20--%3E%20NI%5B%22New%20ingestion%22%5D%0A%20%20%20%20%20%20%20%20NI%20--%3E%20NL%5B%22Lakehouse%20%E2%80%94%20medallion%22%5D%0A%20%20%20%20%20%20%20%20NL%20--%3E%20NM%5B%22New%20marts%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Router%5B%22Consumption%20router%22%5D%0A%20%20%20%20%20%20%20%20R%5B%22Traffic%20router%20%E2%80%94%20per-consumer%20config%22%5D%0A%20%20%20%20%20%20%20%20PAR%5B%22Parity%20harness%20%E2%80%94%20row%2C%20aggregate%2C%20schema%20checks%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Consumers%5B%22Consumers%22%5D%0A%20%20%20%20%20%20%20%20BI%5B%22BI%20and%20reports%22%5D%0A%20%20%20%20%20%20%20%20DN%5B%22Downstream%20systems%22%5D%0A%20%20%20%20end%0A%20%20%20%20LDW%20--%3E%7C%22dual-run%22%7C%20PAR%0A%20%20%20%20NM%20--%3E%7C%22dual-run%22%7C%20PAR%0A%20%20%20%20PAR%20--%3E%7C%22parity%20pass%20%E2%80%94%20route%22%7C%20R%0A%20%20%20%20R%20--%3E%20BI%0A%20%20%20%20R%20--%3E%20DN%0A%20%20%20%20LDW%20-.-%3E%7C%22old%20path%22%7C%20R%0A%20%20%20%20NM%20-.-%3E%7C%22new%20path%22%7C%20R%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[n(" Loading... ",-1)])]),_:1})),e[15]||(e[15]=r('<ol><li><strong>Inventory first</strong>: classify all 3,000 jobs by consumer criticality, complexity, and data volume — the migration order is a portfolio decision (high-value, low-complexity first).</li><li>Each migrated pipeline runs in <strong>dual-run</strong>: the new lakehouse path produces output alongside the legacy output.</li><li>The <strong>parity harness</strong> compares: row counts, aggregate checksums, schema, and sampled row-level values — per table, per run.</li><li>The <strong>router</strong> sends consumers to legacy by default; a pipeline flips to the new path only after passing its parity gate for a defined window (e.g., 7 consecutive daily runs).</li><li>Legacy decommissions per-pipeline only after the new path has run in prod — not just in parity — for a soak period.</li></ol><h3 id="capacity-estimate-4" tabindex="-1">Capacity estimate <a class="header-anchor" href="#capacity-estimate-4" aria-label="Permalink to &quot;Capacity estimate&quot;">​</a></h3><ul><li><strong>Timeline driver</strong>: not compute — it&#39;s parity iteration. Assume ~30% of pipelines fail first parity for semantic (not technical) reasons; budget 2-3 parity cycles per pipeline.</li><li><strong>Dual-run cost</strong>: you pay 2x compute during migration — for a 12-month program that&#39;s the largest single line item. Scope dual-run to the <em>serving</em> layer only where possible (compare marts, not every intermediate).</li><li><strong>Job triage math</strong>: 3,000 jobs ÷ ~20 pipelines/week throughput for a 6-person migration team ≈ 12-18 months — if throughput is lower, the program needs more parallelism, not more time pressure.</li><li><strong>Rollback cost</strong>: keeping the old stack warm ≈ 60-80% of its run cost — factor this into the migration business case, not as an afterthought.</li></ul><h3 id="decision-log-4" tabindex="-1">Decision log <a class="header-anchor" href="#decision-log-4" aria-label="Permalink to &quot;Decision log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Options</th><th>Call</th><th>Why</th></tr></thead><tbody><tr><td>Migration pattern</td><td>Big bang vs strangler-fig vs rewrite-first</td><td><strong>Strangler-fig</strong></td><td>Big bang on 3,000 jobs is a resume-generating event</td></tr><tr><td>Parity bar</td><td>Exact match vs tolerance bands</td><td><strong>Exact on keys and counts; tolerance on floats and timestamps</strong></td><td>Legacy systems have latent bugs — 100% exact parity sometimes means re-implementing the bug</td></tr><tr><td>Order</td><td>Easy-first vs value-first vs dependency-first</td><td><strong>Value × risk matrix</strong> — high value, low dependency first</td><td>Easy-first burns a year on jobs nobody reads</td></tr><tr><td>Semantic drift</td><td>Replicate legacy bug vs fix in new</td><td>Fix in new, flag as <em>known parity exception</em></td><td>Documented divergence beats replicated bug — but it must be a decision, not a surprise</td></tr></tbody></table><h3 id="failure-modes-4" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes-4" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Mitigation</th></tr></thead><tbody><tr><td>Parity shows mismatch nobody can explain</td><td>Classify: schema drift, filter bug, late-arriving data, or legacy bug — each class has a different fix, and &quot;unknown&quot; blocks cutover</td></tr><tr><td>A pipeline passes parity but breaks under real load</td><td>Parity compares data, not performance — add a load soak to the cutover gate</td></tr><tr><td>Consumers hit the new path silently before it&#39;s ready</td><td>Router is the only access path; direct connections to the new marts are blocked until flip</td></tr><tr><td>The last 10% of jobs never migrate</td><td>They are usually the ones with hidden consumers — freeze the legacy stack to read-only, log actual reads, and let usage data prove which jobs are truly dead</td></tr><tr><td>Migration stalls at 60%</td><td>Strangler programs die of organizational attention loss — a weekly burn-down of remaining pipelines, owned by leadership, is the mitigation</td></tr></tbody></table><h3 id="what-changes-at-10x-4" tabindex="-1">What changes at 10x <a class="header-anchor" href="#what-changes-at-10x-4" aria-label="Permalink to &quot;What changes at 10x&quot;">​</a></h3><ul><li><strong>30,000 jobs</strong>: manual migration dies — you need transpiler automation for the mechanical 70% and humans only for the semantic 30%.</li><li><strong>Cross-region cutover</strong>: the router becomes multi-region traffic management; parity must account for replication lag, not just correctness.</li><li><strong>The platform itself migrates</strong>: the new lakehouse will one day be the legacy — build the <em>parity harness and router as permanent platform primitives</em>, not migration scaffolding.</li></ul><details class="details custom-block"><summary>The parity gate is the entire migration</summary><p>Everything else in this design is detail. The migration is &quot;safe&quot; precisely to the degree the parity harness is trustworthy — a parity framework that misses semantic drift gives false confidence, which is worse than no check. Interviews probe this: &quot;how do you know parity is right?&quot; Answer: run the harness on the legacy system against itself first — if it can&#39;t prove identity, it can&#39;t prove parity.</p></details><h2 id="case-6-—-consistent-hashing-cache-tier-in-front-of-a-hot-serving-layer" tabindex="-1">Case 6 — Consistent-hashing cache tier in front of a hot serving layer <a class="header-anchor" href="#case-6-—-consistent-hashing-cache-tier-in-front-of-a-hot-serving-layer" aria-label="Permalink to &quot;Case 6 — Consistent-hashing cache tier in front of a hot serving layer&quot;">​</a></h2><p><strong>The ask.</strong> A serving layer reads user-facing aggregates — profiles, balances, rankings — at 200k reads/s, and 70% of that traffic hits the same 5% of keys. The backing store is fast but expensive at that concurrency. Design a distributed cache tier that scales horizontally, survives node loss without mass key movement, and absorbs the hot-key tail.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Design implication</th></tr></thead><tbody><tr><td>Nodes join/leave weekly</td><td>Consistent hashing — only ~1/N of keys move per membership change, vs ~all keys under <code>hash % N</code></td></tr><tr><td>Skewed node sizes and uneven spread</td><td>Virtual nodes — each physical node owns ~100+ points on the ring, smoothing load to a few %</td></tr><tr><td>Hot keys dominate reads</td><td>Hot-key mitigation beyond the ring — replication of hot keys, no-TTL pins, local in-process L1</td></tr><tr><td>Cache miss must not stampede the DB</td><td>Cache-aside with request coalescing and jittered TTLs</td></tr><tr><td>Writes must not leave stale reads</td><td>Short TTLs + explicit invalidation on write; write-through only where staleness is intolerable</td></tr></tbody></table>',13)),(s(),o(d,null,{default:t(()=>[a(i,{id:"mermaid-1452",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Keys%5B%22Key%20hash%20space%20%E2%80%94%200%20to%202%5E32%2C%20wraps%20around%22%5D%0A%20%20%20%20%20%20%20%20R((%22ring%22))%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Nodes%5B%22Physical%20nodes%20%E2%80%94%20each%20owns%20many%20virtual%20points%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22Node%20A%20%E2%80%94%20vnodes%20at%2012%20pct%2C%2047%20pct%2C%2083%20pct%22%5D%0A%20%20%20%20%20%20%20%20B%5B%22Node%20B%20%E2%80%94%20vnodes%20at%2025%20pct%2C%2061%20pct%22%5D%0A%20%20%20%20%20%20%20%20C%5B%22Node%20C%20%E2%80%94%20vnodes%20at%2038%20pct%2C%2074%20pct%2C%2095%20pct%22%5D%0A%20%20%20%20end%0A%20%20%20%20K1%5B%22key%20hash%20lands%20on%20ring%22%5D%20--%3E%7C%22walk%20clockwise%20to%20next%20vnode%22%7C%20B%0A%20%20%20%20A%20-.-%3E%20R%0A%20%20%20%20B%20-.-%3E%20R%0A%20%20%20%20C%20-.-%3E%20R%0A%20%20%20%20K1%20-.-%3E%20R%0A"})]),fallback:t(()=>[...e[5]||(e[5]=[n(" Loading... ",-1)])]),_:1})),(s(),o(d,null,{default:t(()=>[a(i,{id:"mermaid-1453",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Read%5B%22Read%20path%20%E2%80%94%20cache-aside%22%5D%0A%20%20%20%20%20%20%20%20S1%5B%221%20hash%20key%2C%20walk%20ring%20to%20owner%22%5D%0A%20%20%20%20%20%20%20%20S2%5B%222%20hit%20%E2%80%94%20return%22%5D%0A%20%20%20%20%20%20%20%20S3%5B%223%20miss%20%E2%80%94%20singleflight%20to%20DB%22%5D%0A%20%20%20%20%20%20%20%20S4%5B%224%20populate%20with%20jittered%20TTL%22%5D%0A%20%20%20%20end%0A%20%20%20%20S1%20--%3E%20S2%0A%20%20%20%20S1%20--%3E%20S3%0A%20%20%20%20S3%20--%3E%20S4%0A"})]),fallback:t(()=>[...e[6]||(e[6]=[n(" Loading... ",-1)])]),_:1})),e[16]||(e[16]=r('<ol><li>Each physical node registers ~100-150 <strong>virtual nodes</strong> on the ring; a key&#39;s owner is the first vnode clockwise from <code>hash(key)</code>.</li><li>A node failure shifts only the arcs adjacent to its vnodes — spread across all surviving nodes, not one neighbor.</li><li>Reads are <strong>cache-aside</strong>: check cache, miss → fetch DB, populate, return. A singleflight/lease per key ensures one concurrent DB fill per key, not 10k.</li><li>TTLs get ±10-20% jitter so a bulk-warmed tier does not expire in unison (thunder herd).</li><li>The top hot keys are detected by access counters, then replicated to every node or pinned with no TTL and refreshed asynchronously — the hot-key tail, not the ring, is what actually saturates nodes.</li></ol><h3 id="capacity-estimate-5" tabindex="-1">Capacity estimate <a class="header-anchor" href="#capacity-estimate-5" aria-label="Permalink to &quot;Capacity estimate&quot;">​</a></h3><ul><li><strong>Working set</strong>: 500M keys × ~1 KB ≈ <strong>500 GB</strong> — fits comfortably on 8-10 cache nodes at 64-96 GB each, leaving headroom for vnode rebalancing.</li><li><strong>Traffic</strong>: 200k reads/s; at a 95% hit rate the DB sees ~10k/s — the tier&#39;s job is to keep misses below the DB&#39;s comfort zone, not to reach 100%.</li><li><strong>Hot key math</strong>: if one key takes 5% of reads, that is <strong>10k reads/s on one vnode owner</strong> — a single node&#39;s ceiling. Hot-key replication to all nodes divides that by N.</li><li><strong>Rebalance cost</strong>: adding a node moves ~1/(N+1) of the keyspace; with 10 nodes, ~9% of keys re-home — cheap. Under <code>hash % N</code>, adding a node re-homes ~90%.</li></ul><h3 id="decision-log-5" tabindex="-1">Decision log <a class="header-anchor" href="#decision-log-5" aria-label="Permalink to &quot;Decision log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Options</th><th>Call</th><th>Why</th></tr></thead><tbody><tr><td>Read pattern</td><td>Cache-aside vs read-through vs refresh-ahead</td><td><strong>Cache-aside + singleflight</strong></td><td>Read-through couples app to cache client logic; refresh-ahead wastes writes on cold keys</td></tr><tr><td>Write pattern</td><td>Write-through vs write-around vs write-back</td><td><strong>Write-around + invalidate</strong></td><td>Writes are rare and reads dominate; write-back risks loss, write-through adds write latency the path does not need</td></tr><tr><td>Hot keys</td><td>More vnodes vs dedicated replicas vs local L1</td><td><strong>Replicate to all nodes + short in-process L1</strong></td><td>Vnodes smooth <em>average</em> load but cannot fix a single-key ceiling — only fan-out fixes that</td></tr><tr><td>Membership metadata</td><td>Gossip ring vs coordinator-managed</td><td>Coordinator-managed ring map</td><td>Gossip converges slowly; a wrong ring map routes misses to dead nodes — correctness of the map beats decentralization here</td></tr></tbody></table><h3 id="failure-modes-5" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes-5" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Mitigation</th></tr></thead><tbody><tr><td>Mass TTL expiry stampede (thunder herd)</td><td>Jittered TTLs; on miss, a per-key lease lets exactly one request fill while others wait or serve stale</td></tr><tr><td>Hot key expires mid-spike (cache breakdown)</td><td>Top-N keys get no TTL + background async refresh — the 80/20 keys never expire on a clock</td></tr><tr><td>Requests for nonexistent keys hammer the DB (cache penetration)</td><td>Cache null results with short TTL, or front the tier with a Bloom filter for &quot;definitely absent&quot; keys</td></tr><tr><td>Whole tier down (cache crash)</td><td>Circuit breaker at the client + multi-AZ cache nodes; the DB must survive a brown-out anyway — never let the cache be a hidden single point of load</td></tr><tr><td>Stale reads after write</td><td>Version-stamped keys or explicit delete-on-write; where staleness is intolerable, that slice gets write-through or bypasses the tier</td></tr></tbody></table><h3 id="what-changes-at-10x-5" tabindex="-1">What changes at 10x <a class="header-anchor" href="#what-changes-at-10x-5" aria-label="Permalink to &quot;What changes at 10x&quot;">​</a></h3><ul><li><strong>2M reads/s</strong>: client-side request routing needs the ring map pushed to clients (smart clients) — proxying every read through a routing tier adds a hop and a bottleneck.</li><li><strong>Hot-key churn</strong>: at this scale the top keys rotate hourly; static pinning dies — hot-key detection becomes a small continuous stream job (count-min sketch over access logs) feeding a replication set.</li><li><strong>Multi-region</strong>: a single ring per region, not a global ring — cross-region key ownership turns a cache lookup into a WAN call.</li></ul><h2 id="case-7-—-metrics-and-monitoring-pipeline" tabindex="-1">Case 7 — Metrics and monitoring pipeline <a class="header-anchor" href="#case-7-—-metrics-and-monitoring-pipeline" aria-label="Permalink to &quot;Case 7 — Metrics and monitoring pipeline&quot;">​</a></h2><p><strong>The ask.</strong> The platform is 300 services emitting metrics. Engineers need dashboards, SLO burn alerts, and the ability to slice any metric by service, endpoint, and region — without one team&#39;s debug label taking down the monitoring backend.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Design implication</th></tr></thead><tbody><tr><td>300 services, per-second granularity</td><td>Push from agents into a horizontally scalable ingest tier; storage is a time-series engine, not a general database</td></tr><tr><td>Arbitrary labels per metric</td><td>Cardinality is <em>the</em> capacity problem — bound label space at emit time</td></tr><tr><td>Alerts on SLOs, not just thresholds</td><td>A rules tier evaluating recorded queries over the same store, so alert math matches dashboard math</td></tr><tr><td>Bursty failure modes</td><td>The monitoring pipeline must be <em>more</em> reliable than what it monitors — isolated infra, buffered agents</td></tr></tbody></table>',12)),(s(),o(d,null,{default:t(()=>[a(i,{id:"mermaid-1714",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Emit%5B%22Emission%22%5D%0A%20%20%20%20%20%20%20%20SVC%5B%22Services%20%E2%80%94%20client%20libs%20or%20pushgateway%22%5D%0A%20%20%20%20%20%20%20%20AGT%5B%22Node%20agents%20%E2%80%94%20host%20metrics%2C%20scrape%20or%20push%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Ingest%5B%22Ingest%20and%20routing%22%5D%0A%20%20%20%20%20%20%20%20GW%5B%22Push%20gateway%20%2F%20ingest%20endpoint%20%E2%80%94%20auth%2C%20rate%20limit%22%5D%0A%20%20%20%20%20%20%20%20AGG%5B%22Aggregators%20%E2%80%94%20rollup%2C%20dedupe%20HA%20pairs%2C%20relabel%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Store%5B%22Storage%22%5D%0A%20%20%20%20%20%20%20%20TS%5B%22Time-series%20DB%20%E2%80%94%20chunked%2C%20compressed%2C%20tiered%22%5D%0A%20%20%20%20%20%20%20%20CQ%5B%22Continuous%20queries%20%E2%80%94%20pre-computed%20rollups%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Consume%5B%22Consumption%22%5D%0A%20%20%20%20%20%20%20%20GR%5B%22Dashboards%20and%20query%20API%22%5D%0A%20%20%20%20%20%20%20%20AL%5B%22Alert%20rules%20engine%20%E2%80%94%20routes%20to%20pager%2Fchat%22%5D%0A%20%20%20%20end%0A%20%20%20%20SVC%20--%3E%7C%22push%20or%20scraped%22%7C%20GW%0A%20%20%20%20AGT%20--%3E%20GW%0A%20%20%20%20GW%20--%3E%20AGG%0A%20%20%20%20AGG%20--%3E%20TS%0A%20%20%20%20TS%20--%3E%20CQ%0A%20%20%20%20TS%20--%3E%20GR%0A%20%20%20%20CQ%20--%3E%20GR%0A%20%20%20%20TS%20--%3E%20AL%0A%20%20%20%20CQ%20--%3E%20AL%0A"})]),fallback:t(()=>[...e[7]||(e[7]=[n(" Loading... ",-1)])]),_:1})),e[17]||(e[17]=r('<ol><li>Services and node agents emit metrics — either <strong>pulled</strong> (a scraper fetches <code>/metrics</code>) or <strong>pushed</strong> (agents POST to an ingest endpoint).</li><li>The ingest tier authenticates, rate-limits per emitter, and normalizes labels — this is where a rogue emitter is contained.</li><li>Aggregators dedupe HA scraper pairs and compute rollups (sum by service, drop high-cardinality labels) before storage.</li><li>The time-series store chunks by time, compresses run-length/delta, and tiers: raw for days, 1-minute rollups for months, 1-hour for a year.</li><li>Dashboards and the alert engine query the same store and the same rollup tables — alert math and chart math can never diverge.</li></ol><h3 id="capacity-estimate-6" tabindex="-1">Capacity estimate <a class="header-anchor" href="#capacity-estimate-6" aria-label="Permalink to &quot;Capacity estimate&quot;">​</a></h3><ul><li><strong>Series count</strong>: 300 services × ~200 metrics × ~50 label combos ≈ <strong>3M active series</strong> — fine. The same metrics with <code>user_id</code> or <code>request_id</code> as a label ≈ billions of series — dead. Cardinality, not samples, is the bill.</li><li><strong>Samples</strong>: 3M series at 15s scrape ≈ 200k samples/s — a mid-size time-series cluster; compressed at ~1-2 bytes/sample ≈ <strong>~15-30 GB/day</strong>.</li><li><strong>Query load</strong>: dashboards poll on refresh; 500 dashboard users × 10 panels × 30s refresh ≈ ~1.7k queries/min — trivial. Alert evaluation is the steady query load: ~2k rules × 1/min.</li><li><strong>Retention math</strong>: raw 30d + 1m rollup 400d + 1h rollup 3y cuts storage ~20x vs raw-everything; rollups also cut query time by pre-answering the common grain.</li></ul><h3 id="pull-vs-push-monitoring" tabindex="-1">Pull vs push monitoring <a class="header-anchor" href="#pull-vs-push-monitoring" aria-label="Permalink to &quot;Pull vs push monitoring&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Axis</th><th>Pull (scrape)</th><th>Push (emit)</th></tr></thead><tbody><tr><td>Target discovery</td><td>Registry-driven — the scraper <em>knows</em> what should exist</td><td>Emitters self-select; detecting silent emitters needs an up-check per job</td></tr><tr><td>Short-lived jobs</td><td>Batch jobs die before scrape — metrics lost</td><td>Natural fit — push at end of run</td></tr><tr><td>Failure signal</td><td>Scrape failure <em>is</em> a signal — target down shows up as missing series</td><td>Silence is ambiguous — emitter dead, network dead, or gateway down?</td></tr><tr><td>Load control</td><td>Scraper controls cadence; hard to overload</td><td>Emitters can flood the gateway — needs per-emitter rate limits</td></tr><tr><td>Firewall/NAT</td><td>Needs reachability into every target</td><td>Only the gateway needs to be reachable</td></tr><tr><td>Typical home</td><td>Prometheus-style service monitoring</td><td>StatsD/Grafana Agent-style, edge and IoT fleets</td></tr></tbody></table><p>Most real platforms run both: pull for always-on services, push for batch jobs and edge fleets — the ingest endpoint and the scraper feed the same aggregation tier.</p><h3 id="decision-log-6" tabindex="-1">Decision log <a class="header-anchor" href="#decision-log-6" aria-label="Permalink to &quot;Decision log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Options</th><th>Call</th><th>Why</th></tr></thead><tbody><tr><td>Metric data model</td><td>Wide table in a warehouse vs dedicated TSDB</td><td><strong>Dedicated TSDB</strong></td><td>Warehouse scan-per-query pricing dies at per-second grains and dashboard refresh rates</td></tr><tr><td>High-cardinality labels</td><td>Allow all vs allowlist vs drop-at-ingest</td><td><strong>Allowlist at client + drop at ingest</strong></td><td>Cardinality is unbounded in cost and the failure is total (ingest OOM) — bound it in two places</td></tr><tr><td>Alert evaluation</td><td>In the dashboard tool vs dedicated rules engine</td><td><strong>Dedicated rules engine over the store</strong></td><td>Alerts must fire when the dashboard is closed and must use identical query semantics</td></tr><tr><td>Retention</td><td>All raw vs tiered rollups</td><td><strong>Tiered</strong></td><td>Raw data at 15s granularity is worthless for a 90-day trend; rollups answer trend queries at 1/20th the cost</td></tr></tbody></table><h3 id="failure-modes-6" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes-6" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Mitigation</th></tr></thead><tbody><tr><td>Cardinality explosion — one team adds <code>request_id</code> as a label and ingest falls over</td><td>Label allowlists per metric name at the client lib; ingest drops unlisted labels and emits a <code>dropped_labels</code> counter so the abuse is visible, not silent</td></tr><tr><td>Monitoring dies during the outage it should catch</td><td>Monitoring runs on isolated infra with its own alerting; emitters buffer to local disk when the gateway is unreachable</td></tr><tr><td>Alert storm — one root cause pages 40 teams</td><td>Alert grouping and inhibition in the rules tier; symptom alerts page, cause alerts annotate</td></tr><tr><td>Dashboards scan raw data for 90-day views</td><td>Continuous queries materialize rollups; queries route to the cheapest tier that satisfies the range</td></tr><tr><td>Duplicated series from HA scrapers</td><td>Dedupe at the aggregator — pick one replica per scrape interval</td></tr></tbody></table><h3 id="what-changes-at-10x-6" tabindex="-1">What changes at 10x <a class="header-anchor" href="#what-changes-at-10x-6" aria-label="Permalink to &quot;What changes at 10x&quot;">​</a></h3><ul><li><strong>30M active series</strong>: single-cluster TSDB shards by tenant/team; cross-tenant queries federate. Per-team quotas on series count become a hard budget, like storage quotas.</li><li><strong>Cardinality governance</strong>: label-space review joins schema review — adding a label is a schema change with a cost estimate, not a config tweak.</li><li><strong>Sampling</strong>: at extreme volume, tail sampling or adaptive sample rates trade resolution for cost on low-value metrics — but never on SLO-critical series.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>In monitoring designs, interviewers pivot fast from &quot;how do metrics flow&quot; to &quot;what breaks it.&quot; The book&#39;s framing is right: the pipeline architecture is boring — agents, gateway, aggregator, TSDB, rules — and the interesting engineering is cardinality control, dedupe, and making the observability tier more available than the system it watches.</p></div><h2 id="classic-primitives-that-show-up-in-data-interviews" tabindex="-1">Classic primitives that show up in data interviews <a class="header-anchor" href="#classic-primitives-that-show-up-in-data-interviews" aria-label="Permalink to &quot;Classic primitives that show up in data interviews&quot;">​</a></h2><p>These are the small designs that appear as interview warm-ups or as sub-problems inside bigger asks. Know the shape, the trade-off table, and the follow-up question each one invites.</p><h3 id="rate-limiter-—-token-bucket-vs-leaky-bucket" tabindex="-1">Rate limiter — token bucket vs leaky bucket <a class="header-anchor" href="#rate-limiter-—-token-bucket-vs-leaky-bucket" aria-label="Permalink to &quot;Rate limiter — token bucket vs leaky bucket&quot;">​</a></h3>',16)),(s(),o(d,null,{default:t(()=>[a(i,{id:"mermaid-2026",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20TB%5B%22Token%20bucket%20%E2%80%94%20bursts%20allowed%22%5D%0A%20%20%20%20%20%20%20%20T1%5B%22Tokens%20refill%20at%20r%20per%20second%2C%20cap%20B%22%5D%0A%20%20%20%20%20%20%20%20T2%5B%22Request%20consumes%201%20token%20or%20is%20rejected%22%5D%0A%20%20%20%20%20%20%20%20T1%20--%3E%20T2%0A%20%20%20%20end%0A%20%20%20%20subgraph%20LB%5B%22Leaky%20bucket%20%E2%80%94%20smooth%20output%22%5D%0A%20%20%20%20%20%20%20%20L1%5B%22Requests%20queue%20in%20a%20fixed%20bucket%22%5D%0A%20%20%20%20%20%20%20%20L2%5B%22Bucket%20drains%20at%20constant%20rate%20r%3B%20overflow%20rejected%22%5D%0A%20%20%20%20%20%20%20%20L1%20--%3E%20L2%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[8]||(e[8]=[n(" Loading... ",-1)])]),_:1})),e[18]||(e[18]=r('<table tabindex="0"><thead><tr><th>Axis</th><th>Token bucket</th><th>Leaky bucket</th></tr></thead><tbody><tr><td>Output shape</td><td>Allows bursts up to bucket size, average rate <code>r</code></td><td>Strictly smooth at rate <code>r</code>, bursts absorbed into queue</td></tr><tr><td>Burst tolerance</td><td>Yes — a quiet client gets a burst credit</td><td>No — requests beyond queue length are dropped</td></tr><tr><td>Where it lives</td><td>API rate limits, client-side throttling</td><td>Traffic shaping, egress smoothing, protecting a fragile downstream</td></tr><tr><td>State needed</td><td>Token count + last refill timestamp</td><td>Queue or last-leak timestamp</td></tr></tbody></table><ul><li><strong>Follow-up: where does the state live?</strong> In-process for single-node; Redis with atomic Lua (or a sliding-window counter) for distributed. Discuss clock skew and the race between check-and-decrement.</li><li><strong>Follow-up: what key do you limit on?</strong> API key, user, IP — and layered limits (per-user and global) protect against both one abuser and aggregate load.</li><li><strong>Follow-up: what happens at the limit?</strong> Reject (429 + Retry-After), queue with timeout, or degrade. &quot;Always reject&quot; is rarely the right answer for internal services.</li></ul><h3 id="dedupe-service-—-bloom-filter-trade-offs" tabindex="-1">Dedupe service — Bloom filter trade-offs <a class="header-anchor" href="#dedupe-service-—-bloom-filter-trade-offs" aria-label="Permalink to &quot;Dedupe service — Bloom filter trade-offs&quot;">​</a></h3>',3)),(s(),o(d,null,{default:t(()=>[a(i,{id:"mermaid-2108",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20E%5B%22Incoming%20event%20id%22%5D%20--%3E%20BF%5B%22Bloom%20filter%20%E2%80%94%20k%20hash%20functions%20over%20m%20bits%22%5D%0A%20%20%20%20BF%20--%3E%7C%22definitely%20not%20seen%22%7C%20PASS%5B%22Accept%20and%20set%20bits%22%5D%0A%20%20%20%20BF%20--%3E%7C%22probably%20seen%22%7C%20CHECK%5B%22Check%20authoritative%20store%20%E2%80%94%20or%20treat%20as%20dup%22%5D%0A%20%20%20%20CHECK%20--%3E%7C%22confirmed%20new%22%7C%20PASS%0A%20%20%20%20CHECK%20--%3E%7C%22real%20dup%22%7C%20DROP%5B%22Drop%22%5D%0A"})]),fallback:t(()=>[...e[9]||(e[9]=[n(" Loading... ",-1)])]),_:1})),e[19]||(e[19]=r('<ul><li><strong>The trade-off in one line</strong>: false positives possible, false negatives never — a &quot;probably seen&quot; costs one store lookup, a &quot;definitely not seen&quot; is free. Sizing: ~10 bits per element gives ~1% FP rate; each halving of FP costs ~4.8 bits/element.</li><li><strong>What it cannot do</strong>: delete (use a cuckoo filter), enumerate members, or tell you <em>how many</em> (that&#39;s HyperLogLog). It answers membership only.</li><li><strong>Follow-up: dedupe window is days, filter is RAM.</strong> Rotate filters per window — keep today&#39;s and yesterday&#39;s live, query both, let old ones expire. Never rebuild one giant filter.</li><li><strong>Follow-up: FP = dropped real event.</strong> For idempotency keys where dropping is data loss, the Bloom filter is a <em>pre-filter</em> only — the authoritative uniqueness check is the DB unique constraint. The filter saves lookups, it never makes the decision alone.</li><li><strong>Data-engineering use</strong>: cache-penetration guard (&quot;does this key exist?&quot;), seen-id pre-filter in joins, and dedupe at ingestion where the FP cost is a lost row, not a wrong answer.</li></ul><h3 id="consistent-hashing" tabindex="-1">Consistent hashing <a class="header-anchor" href="#consistent-hashing" aria-label="Permalink to &quot;Consistent hashing&quot;">​</a></h3><p>Covered as a full design in Case 6 above, and the theory in <a href="/Data-Knowledge/system-design/data-intensive.html">Data-Intensive Systems</a>. The interview-sized version:</p><ul><li><code>hash(key) % N</code> fails because <em>N changes</em>: every resize remaps nearly every key. Hash both keys and nodes onto a ring; a node owns the arc until the next node clockwise.</li><li><strong>Virtual nodes</strong> fix two problems at once: uneven arc sizes (random node placement is lumpy) and heterogeneous node capacity (bigger nodes get more vnodes).</li><li><strong>Follow-up: how many keys move when a node leaves?</strong> ~1/N of the keyspace, spread across all survivors — not all to one neighbor (which is why vnodes matter: a physical node&#39;s departure should spread its load evenly, not double the next node&#39;s).</li><li><strong>Follow-up: how do clients find the ring?</strong> A coordinator-managed ring map pushed to smart clients beats gossip when correctness of routing matters — same call as Case 6&#39;s decision log.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>The classic interview mistake is citing these primitives as brand names — &quot;I&#39;d use a Bloom filter&quot; — without the trade-off. Every one of these is a <em>bet</em>: token bucket bets bursts are OK, Bloom bets a false positive is cheap, consistent hashing bets reshuffles are rarer than lookups. State the bet and its failure cost, and the follow-up answers itself.</p></div><h2 id="recurring-platform-decisions" tabindex="-1">Recurring platform decisions <a class="header-anchor" href="#recurring-platform-decisions" aria-label="Permalink to &quot;Recurring platform decisions&quot;">​</a></h2><p>Across all cases the same axes keep appearing — the table is the interview cheat sheet:</p><table tabindex="0"><thead><tr><th>Decision axis</th><th>Option A</th><th>Option B</th><th>Choose A when</th><th>Choose B when</th></tr></thead><tbody><tr><td><strong>Build vs buy — ingestion</strong></td><td>Managed connectors</td><td>Custom ingestion</td><td>Sources are standard (databases, SaaS)</td><td>Custom sources, unusual SLAs, scale cost exceeds license</td></tr><tr><td><strong>Build vs buy — orchestration</strong></td><td>Managed scheduler</td><td>Self-hosted Airflow/Dagster</td><td>Team under ~10 engineers</td><td>Existing platform team, custom scheduling logic</td></tr><tr><td><strong>Build vs buy — catalog</strong></td><td>Cloud-native catalog</td><td>Open-source metastore</td><td>Speed to value, small platform team</td><td>Multi-cloud, deep lineage customization</td></tr><tr><td><strong>Centralize vs federate</strong></td><td>Central DE team owns all</td><td>Domain-owned data products</td><td>Under ~15 teams, early platform</td><td>Over ~20 teams, domain expertise matters</td></tr><tr><td><strong>Batch-first vs stream-first</strong></td><td>Batch/micro-batch default</td><td>Streaming default</td><td>Freshness over ~15 min suffices</td><td>Serving latency or event-driven consumers require it</td></tr><tr><td><strong>One engine vs best-of-breed</strong></td><td>Single compute engine</td><td>Specialized engines per workload</td><td>Team simplicity, moderate scale</td><td>Distinct workloads with divergent cost/latency profiles</td></tr><tr><td><strong>Governance model</strong></td><td>Centralized gatekeeping</td><td>Self-serve with guardrails</td><td>Regulated, low team count</td><td>High team count — gates become bottlenecks</td></tr><tr><td><strong>Migration strategy</strong></td><td>Big bang</td><td>Strangler-fig</td><td>Small, low-risk scope</td><td>Large scope, zero-downtime requirement</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Notice the pattern: almost every &quot;A vs B&quot; resolves to &quot;B when you outgrow the org that could run A.&quot; Platform design is capacity planning for <em>teams</em>, not just systems — the 10x section in every case above is really &quot;what happens when the coordination model breaks.&quot;</p></div><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',10)),a(l,{questions:[{q:"A product team asks to write directly into the lakehouse gold layer, bypassing silver conformance. What is the right platform answer?",options:["Allow it — domain autonomy means they can write anywhere","Allow it with a warning — speed matters more than process","Allow it only for their own domain tables","Block it — gold must be derived from platform-conformed silver or the contract boundary is meaningless"],correct:3,explain:"The mesh-lite contract is ownership of gold in exchange for conformance through silver. Bypassing silver breaks dedupe, contracts, and PII tagging for every consumer downstream — the boundary exists to protect other teams, not to slow this one down."},{q:"A feature store shows a 40% accuracy drop between offline training metrics and online serving. What is the most likely root cause?",options:["The Kafka consumer lag is too high","The feature definitions diverged — training uses latest values instead of point-in-time joins","The online Redis cluster is overloaded","The model checkpoint is stale"],correct:1,explain:"Training-serving skew from point-in-time violations is the canonical failure — the model trained on future information. Symptom: looks great offline, fails in production. The fix is one registry definition compiled to both paths, not tuning the serving store."},{q:"Dashboard traffic to your metrics layer grows 10x in a quarter. What is the cheapest correct response?",options:["Materialize the top query shapes as pre-aggregates and add a result-cache tier","Force all dashboard queries to use a 24-hour cached result","Move dashboards to a different BI tool","Add more warehouse compute to absorb the query load"],correct:0,explain:"Most dashboard queries are repeat shapes — pre-aggregation plus result caching eliminates the redundant scans. Scaling compute for identical queries is paying to recompute the same answer; a fixed TTL ignores the freshness watermark and can serve results past SLO."},{q:"A GDPR erasure request completes and the verification job still finds the user token in a warehouse cache. What does the design need?",options:["Explicit cache invalidation keys in the delete manifest plus a T+SLA re-verification job","Manual cache flushes on each erasure request","Nothing — cache entries expire on TTL anyway","A bigger cache to reduce hit rates"],correct:0,explain:"Compliance cannot rely on TTL expiry — it is a probabilistic delete, not a verifiable one. The delete manifest must carry explicit invalidation keys for every cache tier, and the verification job must re-check after the SLA window, not just once."},{q:"During dual-run migration, one table shows a persistent 0.3% row mismatch. What is the correct next step?",options:["Increase the parity tolerance to 0.5%","Cut over anyway — 0.3% is within tolerance","Classify the mismatch — schema drift, filter bug, late data, or legacy bug — before any cutover decision","Rewind the migration for that table"],correct:2,explain:"An unexplained 0.3% mismatch is a signal, not noise — it can be a filter bug, late-arriving data, or a latent legacy bug. Each class has a different fix, and cutover on an unexplained diff is how migrations ship silent data loss."},{q:"At 10x scale, which layer of the greenfield lakehouse design breaks first?",options:["The medallion bronze layer becomes too large","The catalog and governance plane — a flat catalog and manual stewardship do not scale to hundreds of data products","The object store runs out of capacity","The ingestion connectors hit rate limits"],correct:1,explain:"Storage and ingest scale horizontally almost without thinking; coordination does not. At hundreds of teams, discovery, ownership, policy evaluation, and stewardship review become the bottleneck — which is why the design delegates ownership to domains from day one."}]}),a(l,{questions:[{q:"Why does consistent hashing beat key-hash-mod-N when a cache node is added?",options:["It guarantees perfectly even load distribution","Only about 1/N of keys get remapped vs nearly all of them","It removes the need for replicas","It is faster per lookup"],correct:1,explain:"Mod-N remaps nearly the whole keyspace every time N changes. A hash ring moves only the arcs adjacent to the joining node — about 1/N of keys. Evenness still needs virtual nodes; consistent hashing alone does not guarantee balance."},{q:"A hot key takes 10k reads/s on its owning cache node and saturates it. What actually fixes it?",options:["Replicate the hot key across nodes or pin it with async refresh","Use a bigger node","Add more virtual nodes","Lower the TTL so it refreshes more often"],correct:0,explain:"Vnodes smooth average load but cannot split one key — a single key still maps to a single owner. Only fan-out — replicating the hot key to many nodes, or an in-process L1 plus a no-TTL pin with background refresh — divides the read load."},{q:"A team adds request_id as a metric label and the monitoring ingest falls over. What is the failure?",options:["Scrape timeout","Alert storm","Push-versus-pull mismatch","Cardinality explosion — unbounded label space multiplies series count"],correct:3,explain:"Time-series cost scales with active series, not samples. A high-cardinality label like request_id multiplies each metric into millions of series and kills ingest. Mitigate with label allowlists at the client and unlisted-label drops at the ingest tier."}]}),e[20]||(e[20]=r('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://bytebytego.com/courses/system-design-interview/a-framework-for-system-design-interviews" target="_blank" rel="noreferrer">ByteByteGo — A Framework for System Design Interviews</a> — the requirements → high-level → deep-dive structure every case here follows. <em>Inspiration for this chapter&#39;s format.</em></li><li><a href="https://bytebytego.com/courses/system-design-interview/scale-from-zero-to-millions-of-users" target="_blank" rel="noreferrer">ByteByteGo — Scale From Zero to Millions of Users</a> — the capacity-estimation and &quot;what changes at scale&quot; discipline applied throughout. <em>Inspiration for this chapter&#39;s format.</em></li><li><a href="https://netflixtechblog.com/data-mesh-a-data-movement-and-processing-platform-netflix-1288bcab2873" target="_blank" rel="noreferrer">Netflix — Data Mesh: A Data Movement and Processing Platform</a> — the real-world version of Case 1&#39;s mesh-lite ownership model.</li><li><a href="https://careersatdoordash.com/blog/doordash-clusterless-ml-feature-store" target="_blank" rel="noreferrer">DoorDash — Lessons learned building a clusterless ML feature store</a> — production decisions behind Case 2&#39;s online/offline split.</li><li><a href="https://medium.com/airbnb-engineering/airbnb-metric-computation-with-minerva-part-2-9afe6695b486" target="_blank" rel="noreferrer">Airbnb — Metric computation with Minerva, Part 2</a> — the semantic-layer design Case 3 is modeled on.</li><li><a href="https://www.uber.com/blog/apache-hudi-at-uber" target="_blank" rel="noreferrer">Uber — Apache Hudi at Uber: trillion-record-scale lake operations</a> — the storage layer and incremental-processing reality behind Cases 1 and 4.</li><li><a href="https://engineering.fb.com/2026/05/12/data-infrastructure/migrating-data-ingestion-systems-at-meta-scale/" target="_blank" rel="noreferrer">Meta — Migrating data ingestion systems at Meta scale</a> — Case 5&#39;s strangler-fig and dual-run discipline at extreme scale.</li><li><a href="https://cloud.google.com/blog/products/data-analytics/after-lambda-exactly-once-processing-in-google-cloud-dataflow-part-1" target="_blank" rel="noreferrer">Google Cloud — After Lambda: exactly-once processing in Dataflow</a> — why Case 3&#39;s unified stream-batch design beats a lambda architecture.</li><li><strong>ByteByteGo Big Archive: System Design</strong> — ByteByteGo (2025), <a href="https://bytebytego.com" target="_blank" rel="noreferrer">bytebytego.com</a> — cache failure modes (thunder herd, penetration, breakdown, crash), the 12-algorithm interview list, and the pull/push monitoring trade-offs behind Cases 6-7 and the primitives section.</li></ul>',2))])}const A=c(g,[["render",m]]);export{k as __pageData,A as default};
